/**
 * Peta status Pengajuan Cuti → warna badge, plus format ringkas untuk kartu.
 *
 * Nama status mengikuti state Workflow "Persetujuan Cuti" persis. Warnanya
 * disamakan dengan indikator di desk supaya orang yang bolak-balik antara
 * portal dan desk melihat isyarat yang sama:
 *   Draft abu  ·  Menunggu Approval Atasan amber  ·  Menunggu Approval HR oranye
 *   Menunggu Approval Ketua ungu  ·  Approved hijau  ·  Rejected merah
 *   Menunggu Persetujuan Karyawan biru langit — giliran pemohon sendiri
 *   menjawab tawaran Ketua atas hari yang melebihi saldonya
 *
 * Ungu, bukan indigo: preset Tailwind milik frappe-ui tidak memuat palet
 * indigo, sehingga kelasnya tidak pernah ikut ter-build dan badge-nya tampil
 * tanpa warna sama sekali.
 *   Cancelled pink
 */

const STATUS_BADGE = {
	Draft: 'bg-ui-surface-gray-200 text-ui-ink-gray-700',
	'Menunggu Approval Atasan': 'bg-ui-surface-amber-100 text-ui-ink-amber-700',
	'Menunggu Approval HR': 'bg-ui-surface-orange-100 text-ui-ink-orange-700',
	'Menunggu Approval Ketua': 'bg-ui-surface-violet-100 text-ui-ink-violet-700',
	'Menunggu Persetujuan Karyawan': 'bg-ui-surface-sky-100 text-ui-ink-sky-700',
	Approved: 'bg-ui-surface-green-100 text-ui-ink-green-700',
	Rejected: 'bg-ui-surface-red-100 text-ui-ink-red-700',
	Cancelled: 'bg-ui-surface-pink-100 text-ui-ink-pink-700',
}

export function statusBadge(s) {
	return STATUS_BADGE[s] || 'bg-ui-surface-gray-200 text-ui-ink-gray-700'
}

const BULAN = ['Jan', 'Feb', 'Mar', 'Apr', 'Mei', 'Jun', 'Jul', 'Agu', 'Sep', 'Okt', 'Nov', 'Des']

/** "2026-08-14" → "14 Agu 2026" */
export function tanggal(v) {
	if (!v) return '—'
	const m = String(v).match(/^(\d{4})-(\d{2})-(\d{2})/)
	if (!m) return String(v)
	return `${Number(m[3])} ${BULAN[Number(m[2]) - 1]} ${m[1]}`
}

/**
 * Rentang tanggal seringkas mungkin tanpa kehilangan kejelasan:
 *   sehari             → "14 Agu 2026"
 *   sebulan sama       → "14 s.d. 18 Agu 2026"
 *   beda bulan/tahun   → "28 Agu s.d. 2 Sep 2026"
 */
export function rentang(from, to) {
	if (!from) return '—'
	if (!to || from === to) return tanggal(from)

	const a = String(from).match(/^(\d{4})-(\d{2})-(\d{2})/)
	const b = String(to).match(/^(\d{4})-(\d{2})-(\d{2})/)
	if (!a || !b) return `${tanggal(from)} s.d. ${tanggal(to)}`

	if (a[1] === b[1] && a[2] === b[2]) {
		return `${Number(a[3])} s.d. ${Number(b[3])} ${BULAN[Number(a[2]) - 1]} ${a[1]}`
	}
	if (a[1] === b[1]) {
		return `${Number(a[3])} ${BULAN[Number(a[2]) - 1]} s.d. ${Number(b[3])} ${
			BULAN[Number(b[2]) - 1]
		} ${a[1]}`
	}
	return `${tanggal(from)} s.d. ${tanggal(to)}`
}

/** Buang desimal yang tidak perlu: 2.0 → "2", 0.5 → "0,5" */
export function angka(v) {
	const n = Number(v || 0)
	return (Number.isInteger(n) ? String(n) : n.toFixed(1)).replace('.', ',')
}

/**
 * Tanggal perubahan terakhir. Tanpa jam maupun menit.
 *
 * Daftar diurutkan menurut kolom ini, jadi tanpa menampilkannya orang melihat
 * urutan yang tidak bisa dijelaskan. Tahun hanya ditulis bila berbeda dari
 * tahun berjalan — untuk sebagian besar baris cuma jadi kebisingan.
 */
export function waktuUbah(v) {
	const m = String(v || '').match(/^(\d{4})-(\d{2})-(\d{2})/)
	if (!m) return ''
	const [, th, bl, hr] = m
	const tahunIni = String(new Date().getFullYear())
	return `${Number(hr)} ${BULAN[Number(bl) - 1]}${th === tahunIni ? '' : ' ' + th}`
}
